+	var public = 2;
+	return protected + public;
+}
+
+let arguments = 3;
+
+try {
+	null.x;
+} catch (implements) {}
+
+// `await` is not strict-mode-reserved, but it is reserved in module code, so
+// these break in ESM output for the same reason.
+function awaitLocal() {
+	var await = 4;
+	return await;
+}
+class await {}
